import{_ as e,c as a,o as t,a4 as s}from"./chunks/framework.CRCV4hx_.js";const k=JSON.parse('{"title":"Mollie","description":"","frontmatter":{},"headers":[],"relativePath":"mollie.md","filePath":"mollie.md"}'),i={name:"mollie.md"},n=s(`<h1 id="mollie" tabindex="-1">Mollie <a class="header-anchor" href="#mollie" aria-label="Permalink to &quot;Mollie&quot;">​</a></h1><p>You can use Mollie to receive payments from your customers. Mollie is a <strong>redirect gateway</strong>: the customer is sent to Mollie&#39;s hosted checkout to pay, then returned to your site.</p><p>Mollie ships as a separate, maintained add-on (<code>reachweb/resrv-payment-mollie</code>) that is updated for Resrv v6 and implements the v6 <code>PaymentInterface</code>. This page covers the setup required for it to work.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Even though this payment gateway is tested, it&#39;s suggested that you test it in test mode before going live.</p></div><h2 id="install-the-mollie-payment-gateway-add-on" tabindex="-1">Install the Mollie payment gateway add-on <a class="header-anchor" href="#install-the-mollie-payment-gateway-add-on" aria-label="Permalink to &quot;Install the Mollie payment gateway add-on&quot;">​</a></h2><p>First, install the add-on that provides the Mollie payment gateway:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reachweb/resrv-payment-mollie</span></span></code></pre></div><h2 id="setting-up-the-api-key" tabindex="-1">Setting up the API key <a class="header-anchor" href="#setting-up-the-api-key" aria-label="Permalink to &quot;Setting up the API key&quot;">​</a></h2><p>From your Mollie account you need your <code>Live API key</code>.</p><p>For security reasons, your key is not stored in the add-on&#39;s configuration but in your <code>.env</code> file. Add it there:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MOLLIE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div><p>If you have cached your config, remember to clear the config cache after changing the <code>.env</code> file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span></code></pre></div><h2 id="register-the-gateway" tabindex="-1">Register the gateway <a class="header-anchor" href="#register-the-gateway" aria-label="Permalink to &quot;Register the gateway&quot;">​</a></h2><p>You enable Mollie in the <code>config/resrv-config.php</code> file. You have two options.</p><h3 id="recommended-register-it-under-payment-gateways" tabindex="-1">Recommended: register it under <code>payment_gateways</code> <a class="header-anchor" href="#recommended-register-it-under-payment-gateways" aria-label="Permalink to &quot;Recommended: register it under \`payment_gateways\`&quot;">​</a></h3><p>In v6 you can run multiple gateways side by side through the <code>payment_gateways</code> array. Add Mollie as an entry with its class and a label. Because Mollie is a redirect gateway, this is the recommended approach:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;payment_gateways&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;mollie&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;class&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Reach\\ResrvPaymentMollie\\Http\\Payment\\MolliePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;label&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Mollie&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>When more than one gateway is configured, the customer picks a payment method at checkout. You can also attach a per-gateway surcharge or amount limits to this entry. See <a href="./payment-gateways">Payment gateways</a> for the full array shape.</p><div class="tip custom-block"><p class="custom-block-title">Webhook route</p><p>When Mollie runs under <code>payment_gateways</code>, its webhook route is <code>/resrv/api/webhook/mollie</code> (the route key matches the array key). Configure this URL in your Mollie dashboard.</p></div><h3 id="alternative-set-it-as-the-single-gateway" tabindex="-1">Alternative: set it as the single gateway <a class="header-anchor" href="#alternative-set-it-as-the-single-gateway" aria-label="Permalink to &quot;Alternative: set it as the single gateway&quot;">​</a></h3><p>If Mollie is the only gateway you need, set the singular <code>payment_gateway</code> key to its class instead. Find the <code>payment_gateway</code> setting near the end of <code>config/resrv-config.php</code> and swap the Stripe class for Mollie:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;payment_gateway&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Reach\\ResrvPaymentMollie\\Http\\Payment\\MolliePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>With Mollie as your single gateway, its webhook route is the bare <code>/resrv/api/webhook</code> URL (no gateway suffix). The per-gateway <code>/resrv/api/webhook/mollie</code> URL only applies when Mollie runs under the <code>payment_gateways</code> array.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>That&#39;s it! You should now be able to receive payments using Mollie.</p><p>If you want to run Mollie alongside other gateways, add surcharges, or restrict it to certain order values, see <a href="./payment-gateways">Payment gateways</a>. To build your own redirect or inline gateway, see <a href="./custom-payment-gateway">Writing a custom payment gateway</a>.</p>`,27),l=[n];function o(h,p,r,d,c,y){return t(),a("div",null,l)}const u=e(i,[["render",o]]);export{k as __pageData,u as default};
